  const categories = categoriesSaved.length ? categoriesSaved : categoriesSample;
  const products = productsSaved.length ? productsSaved : (furniture ? [{ title: '3 Seater Sofa', tag: 'Premium fabric', price: '₹ 24,999', image: 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=800&q=80' }, { title: 'Queen Bed', tag: 'Solid wood', price: '₹ 36,999', image: 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=800&q=80' }, { title: 'Dining Table Set', tag: '6 seater', price: '₹ 18,500', image: 'https://images.unsplash.com/photo-1617806118233-18e1de247200?auto=format&fit=crop&w=800&q=80' }, { title: 'Wardrobe', tag: '3 door', price: '₹ 20,999', image: 'https://images.unsplash.com/photo-1595428774223-ef52624120d2?auto=format&fit=crop&w=800&q=80' }] : [{ title: 'Vitrified Floor Tile', tag: '800×800 mm', price: '₹ 45 / sq.ft', image: 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80' }, { title: 'Ceramic Wall Tile', tag: '300×600 mm', price: '₹ 35 / sq.ft', image: 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80' }, { title: 'Bathroom Tile', tag: 'Anti-skid finish', price: '₹ 40 / sq.ft', image: 'https://images.unsplash.com/photo-1620626011761-996317b8d101?auto=format&fit=crop&w=800&q=80' }, { title: 'Marble Tile', tag: 'Gloss finish', price: '₹ 130 / sq.ft', image: 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=800&q=80' }]);
  const services = servicesSaved.length ? servicesSaved : [{ title: 'Residential Interiors', description: 'Warm, practical homes designed around you.', image: 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80' }, { title: 'Commercial Interiors', description: 'Welcoming spaces for teams and customers.', image: 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=800&q=80' }, { title: 'Modular Kitchens', description: 'Thoughtful layouts with quality finishes.', image: 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80' }, { title: 'Renovation & Makeover', description: 'Give existing spaces a fresh new look.', image: 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80' }];
