  const highlights = specific.highlights?.length ? specific.highlights : [{ icon: '✦', title: furniture ? 'Premium Quality' : tiles ? 'Wide Range' : 'Creative Design', description: furniture ? 'Durable materials' : tiles ? 'Latest designs' : 'Unique & personalized' }, { icon: '▦', title: furniture ? 'Wide Range' : tiles ? 'Premium Quality' : 'Premium Materials', description: furniture ? 'Modern & classic designs' : tiles ? 'Durable & long lasting' : 'Quality finish selection' }, { icon: '₹', title: furniture ? 'Affordable Prices' : tiles ? 'Best Prices' : 'On Time Delivery', description: furniture ? 'Best value for money' : tiles ? 'Value for your money' : 'Project completion' }, { icon: '✓', title: furniture ? 'Free Delivery' : tiles ? 'Expert Guidance' : 'Customer Satisfaction', description: furniture ? 'Deliveries across locations' : tiles ? 'Personalized support' : 'Your happiness matters' }];
  const videos = (profile.videos || common.videos || []).filter(Boolean);
  const photos = galleryImages.length ? galleryImages : (furniture ? products.map((item) => item.image) : tiles ? categories.map((item) => item.image) : portfolio.map((item) => item.image)).filter(Boolean);
