  const scrollCategoryRow = (direction) => categoryRowRef.current?.scrollBy({ left: direction * Math.max(categoryRowRef.current.clientWidth * 0.8, 280), behavior: 'smooth' });
  const scrollProductRow = (direction) => productRowRef.current?.scrollBy({ left: direction * Math.max(productRowRef.current.clientWidth * 0.8, 280), behavior: 'smooth' });
