  const phone = place.phone || profile.phone || ''; const email = place.email || profile.email || ''; const social = common.socialMedia || {}; const whatsapp = getWhatsAppUrl(social.whatsapp || place.socialLinks?.whatsapp || phone); const website = safeUrl(place.website || profile.website || social.website);
  const address = [place.address, place.location?.area?.name || place.location?.areaText, place.location?.city?.name, place.location?.district?.name, place.location?.state?.name].filter(Boolean).join(', '); const maps = address ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}` : '';
